// 数据参考自 cnpoe.com/poe2/regex 正则工坊，并对照 poe2db.tw 校正分类。
class Poe2RegexItem {
  final String id;
  final String label;
  final String? labelTc;
  final String? en;
  final String cn;
  final String? tc;
  final String? enRegex;
  final String group;
  final String category;
  const Poe2RegexItem({
    required this.id,
    required this.label,
    this.labelTc,
    this.en,
    required this.cn,
    this.tc,
    this.enRegex,
    this.group = '',
    this.category = '',
  });
  bool get isCustom => category.isNotEmpty;
  /// 显示名：繁体模式且存在 labelTc 时用繁体，英文模式且存在 en 时用英文，否则用简体。
  String displayName({required bool isTc, bool isEn = false}) {
    if (isEn) return en ?? label;
    if (isTc) return labelTc ?? label;
    return label;
  }
  Map<String, dynamic> toJson() => {
        'id': id,
        'label': label,
        'labelTc': labelTc ?? '',
        'en': en ?? '',
        'cn': cn,
        'tc': tc ?? '',
        'enRegex': enRegex ?? '',
        'group': group,
        'category': category,
      };
  factory Poe2RegexItem.fromJson(Map<String, dynamic> json) => Poe2RegexItem(
        id: json['id'] as String? ?? '',
        label: json['label'] as String? ?? '',
        labelTc: (json['labelTc'] as String?)?.isEmpty == true
            ? null
            : json['labelTc'] as String?,
        en: (json['en'] as String?)?.isEmpty == true
            ? null
            : json['en'] as String?,
        cn: json['cn'] as String? ?? '',
        tc: (json['tc'] as String?)?.isEmpty == true ? null : json['tc'] as String?,
        enRegex: (json['enRegex'] as String?)?.isEmpty == true
            ? null
            : json['enRegex'] as String?,
        group: json['group'] as String? ?? '',
        category: json['category'] as String? ?? '',
      );
}

